<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import {computed,onMounted,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import { Calculator } from 'lucide-vue-next';import {api} from '../api';import {post,dateText,errorText} from '../saas';import {useSessionStore} from '../stores/session';import ProvincePageState from '../components/ProvincePageState.vue';import './ProvincePages.css';
const session=useSessionStore(),canWrite=computed(()=>session.user?.accountLevel==='PROVINCE'&&session.user.permissions.includes('system:organization:update'));const rows=ref<any[]>([]),options=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),page=ref(1),total=ref(0),workspaceId=ref(''),status=ref(''),period=ref(new Date().toLocaleDateString('sv-SE').slice(0,7)),detail=ref<any>(null);
async function load(){loading.value=true;error.value='';try{if(!options.value.length)options.value=(await api<any>('/oversight/options')).workspaces;const p=new URLSearchParams({page:String(page.value),pageSize:'20'});if(period.value)p.set('period',period.value);if(status.value)p.set('status',status.value);if(workspaceId.value)p.set('workspaceId',workspaceId.value);const r=await api<any>(`/oversight/evaluations?${p}`);rows.value=r.items;total.value=r.total}catch(e){error.value=errorText(e)}finally{loading.value=false}}function search(){page.value=1;load()}
async function generate(){if(!period.value)return ElMessage.warning('请选择评价月份');try{await ElMessageBox.confirm(`根据${period.value}的运行和事项回执计算各市履责评价，已发布结果不会被覆盖。`,'生成评价',{confirmButtonText:'生成草稿',cancelButtonText:'取消'})}catch{return}saving.value=true;try{await post('/oversight/evaluations/generate',{period:period.value});ElMessage.success('评价草稿已生成，请核对指标后发布');await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
async function publish(row:any){let conclusion='';try{conclusion=(await ElMessageBox.prompt(`确认发布${row.cityName??row.workspace?.cityName} ${row.period}履责评价，并填写结论。发布后不再被重新计算覆盖。`,'发布履责评价',{inputType:'textarea',inputValue:row.conclusion??'',inputValidator:(v:string)=>v?.trim().length>=5?true:'请填写至少5字的评价结论',confirmButtonText:'确认发布',cancelButtonText:'取消'})).value}catch{return}saving.value=true;try{const r=await post<any>(`/oversight/evaluations/${row.id}/publish`,{conclusion});if(detail.value?.id===row.id)detail.value=r;ElMessage.success('评价已发布');await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
const indicators=computed(()=>Array.isArray(detail.value?.breakdown)?detail.value.breakdown:detail.value?.breakdown?.indicators??[]);const weight=(v:any)=>typeof v==='number'?`${v<=1?v*100:v}%`:'—';
onMounted(async()=>{try{options.value=(await api<any>('/oversight/options')).workspaces}catch(e){error.value=errorText(e);return}await load()});
const initialQueryValues = { "period": JSON.parse(JSON.stringify(period.value)), "workspaceId": JSON.parse(JSON.stringify(workspaceId.value)), "status": JSON.parse(JSON.stringify(status.value)) };

function resetQueryFilters() {
  period.value = JSON.parse(JSON.stringify(initialQueryValues["period"]));
  workspaceId.value = '';
  status.value = '';
  page.value = 1;
  search();
}
</script>
<template><section class="province-page"><h1 class="sr-only">地市履责评价</h1><QueryPanel :loading="loading" @search="search" @reset="resetQueryFilters">
<QueryField label="评价月份"><el-date-picker aria-label="评价月份" v-model="period" type="month" value-format="YYYY-MM" placeholder="评价月份" @change="search"/></QueryField>
<QueryField label="城市"><el-select aria-label="城市" v-model="workspaceId" clearable placeholder="全部城市" @change="search"><el-option v-for="o in options" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></QueryField>
<QueryField label="状态"><el-select aria-label="状态" v-model="status" clearable placeholder="全部状态" @change="search"><el-option label="草稿" value="DRAFT"/><el-option label="已发布" value="PUBLISHED"/></el-select></QueryField>
</QueryPanel>
<ListPanel title="履责评价列表" :total="error ? undefined : (total)">
<template #actions><el-button v-if="canWrite" type="primary" :icon="Calculator" :loading="saving" @click="generate">生成本期评价</el-button></template>
<ProvincePageState :error="error" :loading="loading" @retry="load"><el-table :data="rows" empty-text="本期暂无评价，可生成后核对发布"><el-table-column label="城市" min-width="150"><template #default="{row}">{{row.cityName??row.workspace?.cityName}}</template></el-table-column><el-table-column prop="period" label="评价月份" width="120"/><el-table-column label="履责得分" width="110"><template #default="{row}"><strong class="province-grade">{{Number(row.score).toFixed(1)}}</strong></template></el-table-column><el-table-column label="等级" prop="grade" width="100"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':'info'">{{row.status==='PUBLISHED'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="评价结论" prop="conclusion" min-width="280" show-overflow-tooltip/><el-table-column label="发布时间" width="170"><template #default="{row}">{{dateText(row.publishedAt)}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail=row">指标明细</el-button><el-button v-if="canWrite&&row.status==='DRAFT'" link type="primary" :disabled="saving" @click="publish(row)">发布</el-button></template></el-table-column></el-table><div class="province-pagination"><span>共 {{total}} 条评价</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div></ProvincePageState>
</ListPanel>
<el-drawer class="province-drawer" :model-value="!!detail" :title="`${detail?.cityName??detail?.workspace?.cityName??''} · 履责评价`" size="760px" @close="detail=null"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="月份">{{detail.period}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.status==='PUBLISHED'?'已发布':'草稿'}}</el-descriptions-item><el-descriptions-item label="综合得分">{{Number(detail.score).toFixed(1)}}</el-descriptions-item><el-descriptions-item label="等级">{{detail.grade}}</el-descriptions-item></el-descriptions><div class="province-detail-block" style="margin-top:24px"><h3>指标及计算口径</h3><el-table :data="indicators"><el-table-column label="指标" prop="name" min-width="150"/><el-table-column label="观测值" prop="value" width="90"/><el-table-column label="得分" width="80"><template #default="{row}">{{Number(row.score).toFixed(1)}}</template></el-table-column><el-table-column label="权重" width="80"><template #default="{row}">{{weight(row.weight)}}</template></el-table-column><el-table-column label="计算口径" prop="definition" min-width="250"/></el-table></div><div class="province-detail-block"><h3>评价结论</h3><p class="province-description">{{detail.conclusion||'尚未填写发布结论'}}</p></div><el-button v-if="canWrite&&detail.status==='DRAFT'" type="primary" :loading="saving" @click="publish(detail)">发布评价</el-button></template></el-drawer></section></template>
